// Example test illustrating idempotent POST /orders
const res1 = await request(app).post('/orders')
  .set('Idempotency-Key','abc-123')
  .send({ items:[{sku:'SKU1',qty:1}], customerId:'C100' });

const res2 = await request(app).post('/orders')
  .set('Idempotency-Key','abc-123')
  .send({ items:[{sku:'SKU1',qty:1}], customerId:'C100' });

expect(res1.status).toBe(202);
expect(res2.status).toBe(200);
